"""Compare protected-base AST after removing only the added observation spans."""
import ast,hashlib,json,subprocess
from pathlib import Path

BASE='9e5c7c55c708214a13380c9b33dba8c5b35a03c9'
class StripObservations(ast.NodeTransformer):
 def visit_With(self,node):
  self.generic_visit(node)
  node.items=[i for i in node.items if not(isinstance(i.context_expr,ast.Call) and isinstance(i.context_expr.func,ast.Name) and i.context_expr.func.id in ('retention_phase','capture_retention_phases'))]
  return node if node.items else node.body
 def visit_Constant(self,node):
  if isinstance(node.value,str):node.value=' '.join(node.value.split())
  return node

out=[]
for path,method in [('src/pa/domain/projection.py','prune_closed_session_transcripts'),('src/pa/domain/transcript_storage.py','prune'),('src/pa/instance/maintenance.py','_run_maintenance_measured')]:
 old=subprocess.check_output(['git','show',BASE+':'+path]);new=Path(path).read_bytes()
 def method_ast(source):
  nodes=[n for n in ast.walk(ast.parse(source)) if isinstance(n,ast.FunctionDef) and n.name==method]
  assert len(nodes)==1
  return ast.dump(StripObservations().visit(nodes[0]),include_attributes=False)
 before=method_ast(old);after=method_ast(new);assert before==after,path+': non-observation algorithm/control-flow/SQL change'
 out.append({'path':path,'method':method,'baseline_source_sha256':hashlib.sha256(old).hexdigest(),'candidate_source_sha256':hashlib.sha256(new).hexdigest(),'normalized_ast_equal':True,'normalized_ast_sha256':hashlib.sha256(after.encode()).hexdigest()})
value={'base':BASE,'methods':out,'scope':'AST equality after removing ONLY retention_phase/capture_retention_phases context items and normalizing string whitespace. Complements actual SQL trace/data/audit/pin/exception regressions; not timing or deployed acceptance.'}
raw=json.dumps(value,indent=2)+'\n';sha=hashlib.sha256(raw.encode()).hexdigest();p=Path('.dev/retention-phase-semantic-proof.json');p.with_name(p.stem+'.'+sha+'.json').write_text(raw);p.write_text(raw);print(json.dumps({'sha256':sha,'methods':len(out),'all_equal':True}))

